  closePriceSeries() {
    var source = this.binanceOhlcData.length ? this.binanceOhlcData : [
      [Date.now() - 7e3, 620, 628, 616, 624],
      [Date.now() - 6e3, 624, 630, 621, 629],
      [Date.now() - 5e3, 629, 631, 625, 626],
      [Date.now() - 4e3, 626, 636, 625, 634],
      [Date.now() - 3e3, 634, 639, 631, 637],
      [Date.now() - 2e3, 637, 641, 635, 640],
      [Date.now() - 1e3, 640, 642, 633, 635]
    ];
    var data = [];
    var firstClose = source[0][4];
    var hasBoxMovement = false;
    for (var i61 = 0; i61 < source.length; i61++) {
      if (Math.abs(source[i61][4] - firstClose) >= 0.01) {
        hasBoxMovement = true;
      }
      data.push({ x: source[i61][0], y: source[i61][4] });
    }
    if (!hasBoxMovement && data.length > 2) {
      data[1].y = firstClose + 0.02;
      data[2].y = firstClose - 0.02;
    }
    return data;
  }
